* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; color: #263644; background: #eaf2ef; }
body { min-height: 100vh; margin: 0; padding: 24px 16px; display: grid; place-items: center; background: radial-gradient(circle at 15% 10%, #f8e7c7 0, transparent 32%), #eaf2ef; }
.card { width: min(100%, 540px); padding: clamp(22px, 5vw, 38px); border: 1px solid #d9e5df; border-radius: 24px; background: #fffefa; box-shadow: 0 18px 55px #28483b18; text-align: center; }
.eyebrow { margin: 0 0 8px; color: #517267; font-size: 16px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
h1 { margin: 0; color: #213a35; font-size: clamp(28px, 7vw, 38px); line-height: 1.15; }
.intro { max-width: 410px; margin: 14px auto 22px; color: #53645f; font-size: 17px; line-height: 1.55; }
.status { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 14px; text-align: left; }
.status p { margin: 0; font-size: 17px; }
#message { color: #517267; font-weight: 700; text-align: right; }
.board { width: min(100%, 360px); aspect-ratio: 1; margin: 0 auto 24px; display: grid; grid-template-columns: repeat(6, 1fr); gap: 7px; padding: 9px; border-radius: 17px; background: #edf2ed; }
.tile { min-width: 0; border: 0; border-radius: 8px; cursor: pointer; transition: transform .12s ease, filter .12s ease, box-shadow .12s ease; }
.tile:hover { transform: scale(1.06); filter: brightness(1.07); box-shadow: 0 3px 9px #26364430; }
.tile:active { transform: scale(.94); }
.tile:focus-visible, button:focus-visible { outline: 3px solid #263644; outline-offset: 3px; }
.coral { background: #e98270; }
.teal { background: #55a99a; }
.gold { background: #f0c45d; }
.palette { margin: 0; padding: 0; border: 0; }
.palette legend { width: 100%; margin-bottom: 11px; color: #344b44; font-size: 17px; font-weight: 700; }
.swatches { display: flex; justify-content: center; gap: 14px; }
.swatch { width: 52px; height: 52px; border: 3px solid #fffefa; border-radius: 50%; cursor: pointer; box-shadow: 0 0 0 1px #cbd8d1; transition: transform .12s ease, box-shadow .12s ease; }
.swatch:hover { transform: translateY(-2px); }
.swatch[aria-pressed="true"] { box-shadow: 0 0 0 3px #29483f; }
.reset { min-height: 48px; margin-top: 23px; padding: 0 20px; border: 0; border-radius: 12px; background: #29483f; color: white; font: inherit; font-size: 17px; font-weight: 700; cursor: pointer; transition: background .12s ease, transform .12s ease; }
.reset:hover { background: #386357; }
.reset:active { transform: translateY(1px) scale(.98); }
.hint { margin: 17px 0 0; color: #65756f; font-size: 16px; line-height: 1.45; }
@media (max-width: 400px) { body { padding: 14px 10px; } .card { padding: 22px 16px; border-radius: 19px; } .board { gap: 5px; padding: 7px; } .status { align-items: flex-start; } }

const pattern = [
  ['coral','teal','teal','gold','gold','coral'],
  ['coral','coral','teal','gold','coral','coral'],
  ['teal','coral','gold','gold','teal','coral'],
  ['teal','teal','gold','coral','teal','gold'],
  ['gold','teal','coral','coral','gold','gold'],
  ['gold','gold','coral','teal','teal','coral']
];
const board = document.querySelector('#board');
const moveCount = document.querySelector('#move-count');
const message = document.querySelector('#message');
const colorButtons = [...document.querySelectorAll('.swatch')];
let cells;
let moves;
let selectedColor = 'coral';

function render() {
  board.replaceChildren();
  cells.forEach((row, r) => row.forEach((color, c) => {
    const tile = document.createElement('button');
    tile.type = 'button';
    tile.className = `tile ${color}`;
    tile.setAttribute('role', 'gridcell');
    tile.setAttribute('aria-label', `Row ${r + 1}, column ${c + 1}, ${color}`);
    tile.addEventListener('click', () => fill(r, c));
    board.append(tile);
  }));
}

function fill(row, col) {
  const target = cells[row][col];
  if (target === selectedColor || message.textContent === 'One color!') return;
  const stack = [[row, col]];
  const seen = new Set();
  while (stack.length) {
    const [r, c] = stack.pop();
    const key = `${r},${c}`;
    if (r < 0 || r >= 6 || c < 0 || c >= 6 || seen.has(key) || cells[r][c] !== target) continue;
    seen.add(key);
    cells[r][c] = selectedColor;
    stack.push([r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]);
  }
  moves++;
  moveCount.textContent = moves;
  const uniform = cells.every(rowCells => rowCells.every(color => color === cells[0][0]));
  message.textContent = uniform ? 'One color!' : 'Keep connecting colors.';
  render();
}

colorButtons.forEach(button => button.addEventListener('click', () => {
  selectedColor = button.dataset.color;
  colorButtons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
}));

document.querySelector('#reset').addEventListener('click', () => {
  cells = pattern.map(row => [...row]);
  moves = 0;
  moveCount.textContent = moves;
  message.textContent = 'Choose a color to begin.';
  render();
});

document.querySelector('#reset').click();
